const input = Array.isArray(inputs) ? inputs : [inputs];
const maskStr = (str) => {
  if (typeof str !== 'string') return str;
  let res = str;
  if (params.maskEmails) {
    res = res.replace(/([a-zA-Z0-9._-]+)@([a-zA-Z0-9._-]+\.[a-zA-Z0-9._-]+)/gi, (m, u, d) => `${u.slice(0, 2)}***@${d}`);
  }
  if (params.maskPhones) {
    res = res.replace(/\b\d{3}[-.]?\d{3}[-.]?\d{4}\b/g, '***-***-****');
  }
  return res;
};

const redactKeys = (params.redactKeys || '').split(',').map(s => s.trim().toLowerCase()).filter(Boolean);

const sanitizeObj = (val) => {
  if (val === null || val === undefined) return val;
  if (typeof val === 'string') return maskStr(val);
  if (Array.isArray(val)) return val.map(sanitizeObj);
  if (typeof val === 'object') {
    const out = {};
    for (const [k, v] of Object.entries(val)) {
      if (redactKeys.includes(k.toLowerCase())) {
        out[k] = '[REDACTED_PII]';
      } else {
        out[k] = sanitizeObj(v);
      }
    }
    return out;
  }
  return val;
};

helpers.log('Sanitizing data with zero-knowledge PII plugin');
return sanitizeObj(input);

// CSV to JSON Transformer
const firstItem = Array.isArray(inputs) ? inputs[0] : inputs;
const rawCsv = firstItem?.csv || firstItem?.rawContent || (typeof firstItem === 'string' ? firstItem : 'id,name,role,active\n1,Alice,Engineer,true\n2,Bob,Architect,true');

const lines = rawCsv.split(/\r?\n/).filter(line => line.trim().length > 0);
if (lines.length === 0) return [];

const delimiter = params.delimiter || ',';
const headers = lines[0].split(delimiter).map(h => params.trimWhitespace ? h.trim() : h);

const records = lines.slice(1).map((line, idx) => {
  const cells = line.split(delimiter).map(c => params.trimWhitespace ? c.trim() : c);
  const row = { _rowNumber: idx + 1 };
  headers.forEach((h, i) => {
    let val = cells[i] || '';
    if (/^\d+$/.test(val)) val = parseInt(val, 10);
    else if (/^\d+\.\d+$/.test(val)) val = parseFloat(val);
    else if (val.toLowerCase() === 'true') val = true;
    else if (val.toLowerCase() === 'false') val = false;
    row[h] = val;
  });
  return row;
});

helpers.log(`Parsed ${records.length} records from CSV content`);
return records;
